from pathlib import Path
import shutil

ROOT = Path('/home/ubuntu/EdgeSpark-Real-estate-')
GUIDES = ROOT / 'guides'
TEMPLATE = GUIDES

common_note = "This guide is educational information, not legal, tax, financial, valuation, lending, or investment advice. Rules, documents, costs, returns, and market conditions differ by jurisdiction. Before acting, consult appropriately licensed local professionals and verify current official records."

def esc(s):
    return s.replace('\\', '\\\\').replace('#', '\\#').replace('[', '\\[').replace(']', '\\]').replace('&', '\\&')

def page(title, purpose, body, actions):
    bullets = '\\n'.join(f'- {esc(a)}' for a in actions)
    return f'''= {esc(title)}\n\n*Purpose.* {esc(purpose)}\n\n{esc(body)}\n\n*Apply this page*\n{bullets}\n\n#pagebreak()\n'''

def make_doc(folder, title, subtitle, sections, pages=30):
    if folder.exists(): shutil.rmtree(folder)
    folder.mkdir(parents=True)
    shutil.copy(TEMPLATE / 'report-theme.typ', folder / 'report-theme.typ')
    body = []
    body.append(f'''#import "report-theme.typ": report-accent, report-theme\n#show: report-theme.with(title: "{esc(title)}", author: "EdgePark Estate", rhythm: "report", running-header: true)\n#page(margin: (top: 30%, x: 2.2cm), numbering: none, header: none)[\n  #set par(first-line-indent: 0em)\n  #align(center)[\n    #text(size: 26pt, weight: "bold", fill: report-accent)[{esc(title)}]\n    #v(0.5em)\n    #text(size: 14pt, fill: luma(80))[{esc(subtitle)}]\n    #v(2em)\n    #line(length: 40%, stroke: 0.5pt + luma(160))\n    #v(2em)\n    #text(size: 12pt)[EdgePark Estate \\\\ Educational guide \\\\ #datetime.today().display("[year]-[month]-[day]")]\n  ]\n]\n#page(numbering: none, header: none)[\n  #outline(title: [Contents], indent: 1.5em)\n]\n#counter(page).update(1)\n= Reader note\n\n{esc(common_note)}\n\nThis guide is designed to move from principle to practice. Read the examples as scenarios, not forecasts. Keep an evidence file for every property, decision, assumption, conversation, and payment.\n\n#pagebreak()\n''')
    for s in sections:
        body.append(page(*s))
    # Ensure requested length: title + contents + note + one page per section.
    (folder / 'main.typ').write_text(''.join(body), encoding='utf-8')


def sections_for(topic, items):
    out=[]
    for i,(name,focus) in enumerate(items,1):
        out.append((f'{i}. {name}', focus, f'''A durable real-estate decision begins with a clear objective, a defined audience, and a written set of assumptions. In this chapter, translate the idea into evidence you can inspect: location, demand, price, condition, legal status, financing, operating cost, exit route, and the people responsible for each step. Good practice is not about sounding confident; it is about making uncertainty visible early enough to manage it.\n\nUse a simple base case, downside case, and upside case. The base case reflects reasonable current evidence. The downside case tests vacancy, delays, higher costs, weaker demand, or a slower sale. The upside case is useful only when it is supported by a specific, defensible driver. Never use the upside case as the only reason to proceed.''', [f'Write the decision in one sentence and name the evidence needed.', f'List three assumptions that could be wrong and how you will test them.', 'Record the person responsible, deadline, and source for each open question.']))
    return out

